SELECT YEAR(c.signup_date) AS signup_year, CASE WHEN c.city IN ('Chiang Mai', 'London') THEN 'group_a' ELSE 'other' END AS city_group, MAX(we.duration_sec) AS max_duration_sec, AVG(we.duration_sec) AS avg_duration_sec FROM web_events we RIGHT OUTER JOIN sessions s ON we.session_id = s.id LEFT OUTER JOIN customers c ON s.customer_id = c.id GROUP BY YEAR(c.signup_date), CASE WHEN c.city IN ('Chiang Mai', 'London') THEN 'group_a' ELSE 'other' END;
